//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::array::byte_array_set`; the
//! native twin is `benches/native/Bench/ArrayByteArraySet.lean`.
//! the array is updated in place on both sides (Lean's is unique after its first copy of the
//! input, the Rust twin's a copy made once); half the indices are out of bounds (no message)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::array;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<u8>, n: u64) -> u64 {
    let b = &inp[..];
    let mut st = inp.clone();
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        if let Some(k) = array::byte_array_set(st.len(), nat_unbox(nat_box(x >> 51))) {
            st[k] = x as u8;
        }
        acc = mix(acc, u64::from(st[((x >> 40) & 4095) as usize]));
    }
    acc
}

fn main() {
    run(|| byte_operands(), kernel)
}
